# define ROSWASMC_BOUNDED_1_WIIMOTE_TIMEDSWITCH_FOREVER -INT32_C(1)

/** Validate every initialized field without allocation, writes or ROS calls. */
static inline int roswasmc_bounded_1_wiimote_TimedSwitch_valid(roswasmc_bounded_1_wiimote_TimedSwitch const* value)
{
    if(!value)
        return 0;
    if(value->pulse_pattern.size > 16u)
        return 0;
    {
        size_t i;
        for(i = 0; i < value->pulse_pattern.size; ++i)
        {
            {
                uint32_t bits;
                uwvm_bounded_copy(&bits, &value->pulse_pattern.data[i], 4);
                if((bits & UINT32_C(0x7f800000)) == UINT32_C(0x7f800000))
                    return 0;
            }
        }
    }
    return 1;
}

/** Return exact active-prefix wire size; the full value must already be valid. */
static inline size_t roswasmc_bounded_1_wiimote_TimedSwitch_wire_size(roswasmc_bounded_1_wiimote_TimedSwitch const* value)
{
    size_t n = 0;
    n += 1;
    n += 4;
    n += 4;
    if(value->pulse_pattern.size > 16u)
        return 0;
    {
        size_t i;
        for(i = 0; i < value->pulse_pattern.size; ++i)
        {
            n += 4;
        }
    }
    return n;
}

/** Internal writer enters only after full validation, capacity and overlap checks. */
static inline void roswasmc_bounded_1_wiimote_TimedSwitch_write_fields(roswasmc_bounded_1_wiimote_TimedSwitch const* value, unsigned char* p, size_t* offset)
{
    uwvm_bounded_put(p + *offset, (uint64_t)value->switch_mode, 1);
    *offset += 1;
    uwvm_bounded_put(p + *offset, (uint64_t)value->num_cycles, 4);
    *offset += 4;
    uwvm_bounded_put(p + *offset, value->pulse_pattern.size, 4);
    *offset += 4;
    {
        size_t i;
        for(i = 0; i < value->pulse_pattern.size; ++i)
        {
            {
                uint32_t bits;
                uwvm_bounded_copy(&bits, &value->pulse_pattern.data[i], 4);
                uwvm_bounded_put(p + *offset, bits, 4);
                *offset += 4;
            }
        }
    }
}

/** Internal reader fills only the public decoder temporary and checks every cursor move. */
static inline int
    roswasmc_bounded_1_wiimote_TimedSwitch_read_fields(unsigned char const* p, size_t n, size_t* offset, roswasmc_bounded_1_wiimote_TimedSwitch* value)
{
    if(*offset > n || n - *offset < 1)
        return 0;
    {
        uint8_t bits = (uint8_t)uwvm_bounded_get(p + *offset, 1);
        uwvm_bounded_copy(&value->switch_mode, &bits, 1);
    }
    *offset += 1;
    if(*offset > n || n - *offset < 4)
        return 0;
    {
        uint32_t bits = (uint32_t)uwvm_bounded_get(p + *offset, 4);
        uwvm_bounded_copy(&value->num_cycles, &bits, 4);
    }
    *offset += 4;
    if(*offset > n || n - *offset < 4)
        return 0;
    value->pulse_pattern.size = (uint32_t)uwvm_bounded_get(p + *offset, 4);
    *offset += 4;
    if(value->pulse_pattern.size > 16u)
        return 0;
    {
        size_t i;
        for(i = 0; i < value->pulse_pattern.size; ++i)
        {
            if(*offset > n || n - *offset < 4)
                return 0;
            {
                uint32_t bits = (uint32_t)uwvm_bounded_get(p + *offset, 4);
                uwvm_bounded_copy(&value->pulse_pattern.data[i], &bits, 4);
            }
            *offset += 4;
        }
    }
    return roswasmc_bounded_1_wiimote_TimedSwitch_valid(value);
}

/** Encode transactionally: preserve output/length on invalid values or insufficient capacity. */
static inline uint32_t
    roswasmc_bounded_1_wiimote_TimedSwitch_encode(roswasmc_bounded_1_wiimote_TimedSwitch const* value, void* output, size_t capacity, size_t* length)
{
    size_t n, offset = 0;
    if(!length || !roswasmc_bounded_1_wiimote_TimedSwitch_valid(value))
        return UWVM_BOUNDED_INVALID;
    n = roswasmc_bounded_1_wiimote_TimedSwitch_wire_size(value);
    if(capacity < n)
        return UWVM_BOUNDED_TOO_LARGE;
    if((n && !output) || uwvm_bounded_overlap(value, sizeof *value, output, n) || uwvm_bounded_overlap(length, sizeof *length, output, n) ||
       uwvm_bounded_overlap(length, sizeof *length, value, sizeof *value))
        return UWVM_BOUNDED_INVALID;
    roswasmc_bounded_1_wiimote_TimedSwitch_write_fields(value, (unsigned char*)output, &offset);
    *length = offset;
    return 0;
}

/** Decode exact bytes into a temporary; refused/truncated/trailing input leaves value unchanged. */
static inline uint32_t roswasmc_bounded_1_wiimote_TimedSwitch_decode(void const* input, size_t length, roswasmc_bounded_1_wiimote_TimedSwitch* value)
{
    roswasmc_bounded_1_wiimote_TimedSwitch next = {0};
    size_t offset = 0;
    if(!value || (length && !input) || length < 9u || length > 73u || uwvm_bounded_overlap(value, sizeof *value, input, length))
        return UWVM_BOUNDED_INVALID;
    if(!roswasmc_bounded_1_wiimote_TimedSwitch_read_fields((unsigned char const*)input, length, &offset, &next) || offset != length)
        return UWVM_BOUNDED_INVALID;
    *value = next;
    return 0;
}
#endif
#undef UWVM_BOUNDED_ASSERT
